<?php
require_once __DIR__.'/app/lib/Security.php';Security::start();Security::requireRole(['reviewer','admin','super_admin']);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Community Source Collectors · TechSelectAI</title><style>body{font-family:Inter,system-ui,sans-serif;background:#f6f8fb;color:#172033;margin:0}main{max-width:1240px;margin:auto;padding:28px}.panel{background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:16px;margin:0 0 18px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}input,select,button,textarea{padding:9px;border:1px solid #cbd5e1;border-radius:8px;background:#fff;box-sizing:border-box}input,select{width:100%}button{background:#173b63;color:#fff;border:0;cursor:pointer}.secondary{background:#64748b}.warn{background:#fff7ed;border:1px solid #fed7aa;padding:10px;border-radius:9px}.muted{color:#64748b;font-size:12px}table{width:100%;border-collapse:collapse}th,td{padding:9px;border-bottom:1px solid #eef2f7;text-align:left;vertical-align:top}.actions{display:flex;gap:6px;flex-wrap:wrap}@media(max-width:800px){.grid{grid-template-columns:1fr}table{display:block;overflow:auto}}</style></head><body><main><h1>Community Source Collectors</h1><p class="muted">Collect permitted public community evidence into the existing Community Intelligence review workflow. A connector cannot run until a reviewer explicitly marks it permitted.</p><p><a href="/community-intelligence-admin">← Community Intelligence review</a> · <a href="/pri-source-policy">Source policy</a></p><div class="warn"><strong>Collection boundary:</strong> no arbitrary webpage scraper is provided. Supported collectors are Stack Exchange API and explicitly reviewed RSS/Atom feeds. Collected text is temporary, product-matched, deduplicated, AI-filtered, then removed after analysis.</div><section class="panel"><h2>Add connector</h2><div class="grid"><label>Product<select id="product"></select></label><label>Collector<select id="type"><option value="stackexchange_api">Stack Exchange API</option><option value="rss_atom">RSS / Atom feed</option></select></label><label>Source classification<select id="sourceType"><option value="public_forum">Public forum/community</option><option value="vendor_community">Vendor community</option><option value="independent_blog">Independent blog</option><option value="public_case_study">Public case study</option><option value="app_store">App-store feed</option><option value="other_public">Other public</option></select></label><label>Source name<input id="name" placeholder="e.g. Stack Overflow"></label><label>Endpoint/feed URL<input id="url" placeholder="https://api.stackexchange.com/2.3/search/advanced"></label><label>Interval minutes<input id="interval" type="number" min="60" value="1440"></label><label>Stack Exchange site<input id="site" value="stackoverflow"></label><label>Query<input id="query" placeholder="defaults to product name"></label><label>Tag (optional)<input id="tag"></label></div><p><button onclick="createConnector()">Create pending connector</button> <span id="msg" class="muted"></span></p></section><section class="panel"><h2>Collectors</h2><div id="rows">Loading…</div></section></main><script>
let csrf='',products=[];const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function api(path,opt={}){opt.headers={...(opt.headers||{}),'Content-Type':'application/json','X-CSRF-Token':csrf};const r=await fetch(path,opt),d=await r.json().catch(()=>({}));if(d.csrf_token)csrf=d.csrf_token;if(!r.ok)throw new Error(d.error||'Request failed');return d}
async function load(){const d=await api('/api/community-collectors');products=d.products;product.innerHTML=products.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');rows.innerHTML=d.connectors.length?`<table><thead><tr><th>Product/source</th><th>Collector</th><th>Policy</th><th>Schedule</th><th>Pending</th><th>Actions</th></tr></thead><tbody>${d.connectors.map(c=>`<tr><td><strong>${esc(c.product)}</strong><br>${esc(c.source_name)}<br><span class="muted">${esc(c.base_url)}</span></td><td>${esc(c.connector_type)}<br><span class="muted">${esc(c.source_type)}</span></td><td>${esc(c.policy_status)}<br><span class="muted">${esc(c.policy_notes||'')}</span></td><td>Last: ${esc(c.last_run_at||'Never')}<br>Next: ${esc(c.next_run_at||'Not scheduled')}<br>${c.last_error?`<span class="muted">${esc(c.last_error)}</span>`:''}</td><td>${c.pending_items}</td><td><div class="actions"><button onclick="policy(${c.id},'permitted')">Permit</button><button class="secondary" onclick="policy(${c.id},'restricted')">Restrict</button><button class="secondary" onclick="policy(${c.id},'blocked')">Block</button><button onclick="run(${c.id})" ${c.policy_status!=='permitted'?'disabled':''}>Run</button><button onclick="analyze(${c.product_id})" ${+c.pending_items<1?'disabled':''}>Analyze pending</button></div></td></tr>`).join('')}</tbody></table>`:'<p class="muted">No collectors configured.</p>'}
async function createConnector(){try{const body={product_id:+product.value,connector_type:type.value,source_type:sourceType.value,source_name:name.value,base_url:url.value,interval_minutes:+interval.value,config:{site:site.value,query:query.value,tagged:tag.value,pagesize:25,max_items:25}};await api('/api/community-collectors',{method:'POST',body:JSON.stringify(body)});msg.textContent='Created. Review and permit before running.';await load()}catch(e){msg.textContent=e.message}}
async function policy(id,p){const notes=prompt('Policy notes / basis for this decision:','')??'';try{await api(`/api/community-collectors/${id}/policy`,{method:'POST',body:JSON.stringify({policy:p,notes})});await load()}catch(e){alert(e.message)}}async function run(id){try{const d=await api(`/api/community-collectors/${id}/run`,{method:'POST',body:'{}'});alert(`Seen ${d.result.seen}; new ${d.result.new}; duplicate ${d.result.duplicate}; rejected ${d.result.rejected}`);await load()}catch(e){alert(e.message)}}async function analyze(pid){try{const d=await api(`/api/community-collectors/product/${pid}/analyze`,{method:'POST',body:JSON.stringify({limit:25})});alert(`Processed ${d.result.processed||0}. Community Intelligence remains subject to human publication approval.`);await load()}catch(e){alert(e.message)}}load();
</script></body></html>